Graph <- .generator("Graph", list(
  `new` = function(name = "graph") {
    r <- .Call(R_rlx_graph_new, name)
    .check(r[[1]])
    .wrap(r[[2]], "Graph")
  }
))

# A graph split into self-contained parts that run in order: part i reads
# its `imports` from earlier parts' `exports` of the same name.
.methods$rlx_Partition <- list(
  # The number of parts.
  `num_parts` = function(self) {
    r <- .Call(R_rlx_partition_num_parts, self)
    .check(r[[1]])
    r[[2]]
  },
  # A copy of one part's graph.
  `graph` = function(self, part) {
    r <- .Call(R_rlx_partition_graph, self, part)
    .check(r[[1]])
    .wrap(r[[2]], "Graph")
  },
  # The boundary names a part reads.
  `imports` = function(self, part) {
    r <- .Call(R_rlx_partition_imports, self, part)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # The name of each of a part's outputs.
  `exports` = function(self, part) {
    r <- .Call(R_rlx_partition_exports, self, part)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # Where each source output went: [[part, output index], …].
  `outputs` = function(self) {
    r <- .Call(R_rlx_partition_outputs, self)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # The parts as one graph again.
  `merge` = function(self) {
    r <- .Call(R_rlx_partition_merge, self)
    .check(r[[1]])
    .wrap(r[[2]], "Graph")
  }
)

Partition <- .generator("Partition", list(
  # Node i goes to part assign[i] (`node_count()` entries; inputs', params'
  # and constants' are ignored). Every edge must run to the same or a later part.
  `new` = function(graph, assign) {
    r <- .Call(R_rlx_partition_new, graph, assign, length(assign))
    .check(r[[1]])
    .wrap(r[[2]], "Partition")
  },
  # Two parts: `cut` and everything it reads, then the rest.
  `split_at` = function(graph, cut) {
    r <- .Call(R_rlx_partition_split_at, graph, cut, length(cut))
    .check(r[[1]])
    .wrap(r[[2]], "Partition")
  },
  # One part per independent subgraph; the parts import nothing.
  `components` = function(graph) {
    r <- .Call(R_rlx_partition_components, graph)
    .check(r[[1]])
    .wrap(r[[2]], "Partition")
  }
))

# A device and precision to compile graphs for.
.methods$rlx_Session <- list(
  # The device label.
  `device` = function(self) {
    r <- .Call(R_rlx_session_device, self)
    .check(r[[1]])
    r[[2]]
  },
  # "f32", "f16" or "bf16".
  `precision` = function(self) {
    r <- .Call(R_rlx_session_precision, self)
    .check(r[[1]])
    r[[2]]
  },
  # The precision policy's label, if any.
  `policy` = function(self) {
    r <- .Call(R_rlx_session_policy, self)
    .check(r[[1]])
    r[[2]]
  },
  # Compile `graph` (consumed). options: {fusion, kernel_dispatch, policy}.
  `compile` = function(self, graph, options = NULL) {
    r <- .Call(R_rlx_session_compile, self, graph, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    .wrap(r[[2]], "Compiled")
  }
)

Session <- .generator("Session", list(
