  `resolve` = function(self, hint = NULL) {
    r <- .Call(R_rlx_runner_resolve, self, hint)
    .check(r[[1]])
    r[[2]]
  },
  # Candidates: [{device, available, supports_graph, recommended, blocker}].
  `report` = function(self) {
    r <- .Call(R_rlx_runner_report, self)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # Set one f32 parameter on every device.
  `set_param` = function(self, name, data) {
    r <- .Call(R_rlx_runner_set_param, self, name, data, length(data))
    .check(r[[1]])
    invisible(NULL)
  },
  # Set several f32 parameters; returns how many.
  `set_params` = function(self, params) {
    a_params <- .inputs(params)
    r <- .Call(R_rlx_runner_set_params, self, a_params$names, a_params$data, a_params$lens, length(a_params$names))
    .check(r[[1]])
    r[[2]]
  },
  # Set one parameter from raw bytes of `dtype`.
  `set_param_typed` = function(self, name, data, dtype) {
    r <- .Call(R_rlx_runner_set_param_typed, self, name, data, length(data), dtype)
    .check(r[[1]])
    invisible(NULL)
  },
  # Compile for every device now; returns the ones that compiled.
  `warm_all` = function(self) {
    r <- .Call(R_rlx_runner_warm_all, self)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # Time `runs` runs per device: [{device, mean_ms, …}].
  `benchmark` = function(self, inputs, runs = 5) {
    a_inputs <- .inputs(inputs)
    r <- .Call(R_rlx_runner_benchmark, self, a_inputs$names, a_inputs$data, a_inputs$lens, length(a_inputs$names), runs)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # Run on the resolved device (or `hint`).
  `run` = function(self, inputs, hint = NULL) {
    a_inputs <- .inputs(inputs)
    r <- .Call(R_rlx_runner_run, self, a_inputs$names, a_inputs$data, a_inputs$lens, length(a_inputs$names), hint)
    .check(r[[1]])
    list(device = r[[2]], outputs = .Call(R_support_take_outputs, r[[3]]))
  },
  # Run on exactly `device`.
  `run_on` = function(self, device, inputs) {
    a_inputs <- .inputs(inputs)
    r <- .Call(R_rlx_runner_run_on, self, device, a_inputs$names, a_inputs$data, a_inputs$lens, length(a_inputs$names))
    .check(r[[1]])
    .Call(R_support_take_outputs, r[[2]])
  },
  # Try each device of `chain` in order until one runs.
  `run_try` = function(self, chain, inputs) {
    a_chain <- as.character(chain)
    a_inputs <- .inputs(inputs)
    r <- .Call(R_rlx_runner_run_try, self, a_chain, length(a_chain), a_inputs$names, a_inputs$data, a_inputs$lens, length(a_inputs$names))
    .check(r[[1]])
    list(device = r[[2]], outputs = .Call(R_support_take_outputs, r[[3]]))
  },
  # Run on `hint`, falling back down the policy when a device fails.
  `run_chain` = function(self, inputs, hint = NULL) {
    a_inputs <- .inputs(inputs)
    r <- .Call(R_rlx_runner_run_chain, self, a_inputs$names, a_inputs$data, a_inputs$lens, length(a_inputs$names), hint)
    .check(r[[1]])
    list(device = r[[2]], outputs = .Call(R_support_take_outputs, r[[3]]))
  },
  # Resolve with the inputs in hand (shape-aware), then run.
  `run_with_inputs` = function(self, inputs, hint = NULL) {
    a_inputs <- .inputs(inputs)
    r <- .Call(R_rlx_runner_run_with_inputs, self, a_inputs$names, a_inputs$data, a_inputs$lens, length(a_inputs$names), hint)
    .check(r[[1]])
    .Call(R_support_take_outputs, r[[2]])
  }
)

