# A seeded sampler that keeps its own history.
.methods$rlx_Sampler <- list(
  # Sample the next token and record it.
  `next` = function(self, logits) {
    r <- .Call(R_rlx_sampler_next, self, logits, length(logits))
    .check(r[[1]])
    r[[2]]
  },
  # Record prompt tokens (for the repetition penalty).
  `prime` = function(self, ids) {
    r <- .Call(R_rlx_sampler_prime, self, ids, length(ids))
    .check(r[[1]])
    invisible(NULL)
  },
  # Clear the history; reseed when `seed` is given.
  `reset` = function(self, seed = NULL) {
    r <- .Call(R_rlx_sampler_reset, self, seed)
    .check(r[[1]])
    invisible(NULL)
  },
  # Tokens recorded so far.
  `history` = function(self) {
    r <- .Call(R_rlx_sampler_history, self)
    .check(r[[1]])
    r[[2]]
  }
)

Sampler <- .generator("Sampler", list(
  `new` = function(options = NULL) {
    r <- .Call(R_rlx_sampler_new, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    .wrap(r[[2]], "Sampler")
  }
))

# This process's place in a mesh of rlx nodes: point-to-point messages,
# collectives, and the ship-graph protocol (a coordinator ships a stage or a
# training job; generic workers run it on their own hardware).
.methods$rlx_Group <- list(
  # This node's rank.
  `rank` = function(self) {
    r <- .Call(R_rlx_group_rank, self)
    .check(r[[1]])
    r[[2]]
  },
  # Ranks in the mesh.
  `world` = function(self) {
    r <- .Call(R_rlx_group_world, self)
    .check(r[[1]])
    r[[2]]
  },
  # Whether this is rank 0.
  `is_leader` = function(self) {
    r <- .Call(R_rlx_group_is_leader, self)
    .check(r[[1]])
    r[[2]]
  },
  # Wait until every rank arrives.
  `barrier` = function(self) {
    r <- .Call(R_rlx_group_barrier, self)
    .check(r[[1]])
    invisible(NULL)
  },
  # Send f32 values to rank `to` under `tag`.
  `send` = function(self, to, tag, data) {
    r <- .Call(R_rlx_group_send, self, to, tag, data, length(data))
    .check(r[[1]])
    invisible(NULL)
  },
  # Receive f32 values from rank `from` under `tag`.
  `recv` = function(self, from, tag) {
    r <- .Call(R_rlx_group_recv, self, from, tag)
    .check(r[[1]])
    r[[2]]
  },
  # Reduce across every rank: op "sum" | "mean" | "max" | "min".
  `all_reduce` = function(self, data, op = "sum") {
    r <- .Call(R_rlx_group_all_reduce, self, data, length(data), op)
    .check(r[[1]])
    r[[2]]
  },
  # Every rank's values, concatenated in rank order.
  `all_gather` = function(self, data) {
    r <- .Call(R_rlx_group_all_gather, self, data, length(data))
    .check(r[[1]])
    r[[2]]
  },
  # Rank `root`'s values, on every rank; other ranks pass a buffer of the root's length.
  `broadcast` = function(self, root, data) {
    r <- .Call(R_rlx_group_broadcast, self, root, data, length(data))
    .check(r[[1]])
    r[[2]]
  },
  # Coordinator: the capabilities each worker announced, [{rank, devices, platform, role}].
  `collect_caps` = function(self) {
    r <- .Call(R_rlx_group_collect_caps, self)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # Coordinator: ship a stage of `graph` to worker `rank`. options: {input,
  # output, device, weights: {param: uri}, packed: {param: uri}, stage_id}.
  `ship_stage` = function(self, rank, graph, options) {
    r <- .Call(R_rlx_group_ship_stage, self, rank, graph, .json(options))
    .check(r[[1]])
    invisible(NULL)
  },
  # Send an activation to rank `to`.
  `send_activation` = function(self, to, data) {
    r <- .Call(R_rlx_group_send_activation, self, to, data, length(data))
    .check(r[[1]])
    invisible(NULL)
  },
  # Receive an activation from rank `from`.
  `recv_activation` = function(self, from) {
    r <- .Call(R_rlx_group_recv_activation, self, from)
    .check(r[[1]])
    r[[2]]
  },
  # Worker: announce, receive a stage, serve activations until the
  # coordinator finishes (or `steps`). options: {steps}. Returns {rank, device, platform, activations}.
  `serve_worker` = function(self, options = NULL) {
    r <- .Call(R_rlx_group_serve_worker, self, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    .decode(r[[2]])
  },
  # Coordinator: ship a data-parallel training job for backward `graph` to
  # worker `rank`. spec: {params: [{name, uri}], data: [{input, uri, elem,
  # shard_start, shard_len}], grad_start, loss_index, seed_input, momentum,
  # lr_per_epoch, batch, device, push_data}.
  `ship_train` = function(self, rank, graph, spec) {
    r <- .Call(R_rlx_group_ship_train, self, rank, graph, .json(spec))
    .check(r[[1]])
    invisible(NULL)
  },
  # Train this rank's shard of a job in lockstep with the workers; returns
  # {metrics, params}.
  `run_train` = function(self, graph, spec) {
    r <- .Call(R_rlx_group_run_train, self, graph, .json(spec))
    .check(r[[1]])
    .decode(r[[2]])
  },
  # Worker: announce, receive a training job, train in lockstep; returns {rank, platform, metrics, params}.
  `serve_trainer` = function(self, options = NULL) {
    r <- .Call(R_rlx_group_serve_trainer, self, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    .decode(r[[2]])
  }
)

Group <- .generator("Group", list(
  # Join a mesh as `rank` of `world`. options: {peers: ["host:port", …],
  # topology: "mesh" | "star", device: "auto", discover: {port, data_port,
  # via}, heap_mb}. Blocks until every peer connects.
  `connect` = function(rank, world, options = NULL) {
    r <- .Call(R_rlx_group_connect, rank, world, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    .wrap(r[[2]], "Group")
  },
  # Join with RANK / WORLD / PEERS / TOPOLOGY / DEVICE / DISCOVER from the environment.
  `from_env` = function() {
    r <- .Call(R_rlx_group_from_env)
    .check(r[[1]])
    .wrap(r[[2]], "Group")
  }
))

# A model from any provider — an .rlxp package, a plugin's family runner
# (LLMs, speech, vision, …) — opened by path or id and run by name.
.methods$rlx_Model <- list(
  # {provider, family, task, device, inputs: [{name, dtype, shape}], outputs, metadata}.
  `info` = function(self) {
    r <- .Call(R_rlx_model_info, self)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # The task: "graph", "text-generation", "speech-recognition", ….
  `task` = function(self) {
    r <- .Call(R_rlx_model_task, self)
    .check(r[[1]])
    r[[2]]
  },
  # f32 tensors in, f32 tensors out. options: {shapes: {name: dims}, …the model's own}.
  `run` = function(self, inputs, options = NULL) {
    a_inputs <- .inputs(inputs)
    r <- .Call(R_rlx_model_run, self, a_inputs$names, a_inputs$data, a_inputs$lens, length(a_inputs$names), if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    .Call(R_support_take_outputs, r[[2]])
  },
  # Tensors of any dtype in (bytes + dtype), out the same way.
  `run_typed` = function(self, inputs, options = NULL) {
    a_inputs <- .typed_inputs(inputs)
    r <- .Call(R_rlx_model_run_typed, self, a_inputs$names, a_inputs$data, a_inputs$lens, a_inputs$dtypes, length(a_inputs$names), if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    .Call(R_support_take_typed_outputs, r[[2]])
  },
  # Dims of each output of the last run.
  `output_shapes` = function(self) {
    r <- .Call(R_rlx_model_output_shapes, self)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # Names of the outputs of the last run.
  `output_names` = function(self) {
    r <- .Call(R_rlx_model_output_names, self)
    .check(r[[1]])
    .decode(r[[2]])
  },
  # A language model's last-position logits after `ids`.
  `predict_logits` = function(self, ids) {
    r <- .Call(R_rlx_model_predict_logits, self, ids, length(ids))
    .check(r[[1]])
    r[[2]]
  },
  # A language model's next ids after `ids`. options: {temperature, top_p, top_k, seed, stop_ids}.
  `generate` = function(self, ids, max_tokens = 16, options = NULL) {
    r <- .Call(R_rlx_model_generate, self, ids, length(ids), max_tokens, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    r[[2]]
  },
  # Text in, text out, for a model with a tokenizer. options: {max_tokens, temperature, …}.
  `generate_text` = function(self, prompt, options = NULL) {
    r <- .Call(R_rlx_model_generate_text, self, prompt, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    r[[2]]
  },
  # A reply to `messages` ([{role, content}, …], or one string), with the
  # model's chat template applied. options: as generate_text.
  `chat` = function(self, messages, options = NULL) {
    r <- .Call(R_rlx_model_chat, self, .json(messages), if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    r[[2]]
  },
  # The text of mono `audio` at `sample_rate`, for a speech-recognition model.
  `transcribe` = function(self, audio, sample_rate = 16000, options = NULL) {
    r <- .Call(R_rlx_model_transcribe, self, audio, length(audio), sample_rate, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    r[[2]]
  },
  # `text` spoken, for a text-to-speech model: mono samples and their rate.
  `synthesize` = function(self, text, options = NULL) {
    r <- .Call(R_rlx_model_synthesize, self, text, if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    list(audio = r[[2]], sample_rate = r[[3]])
  },
  # One vector per text ([[f32, …], …]), for an embedding model.
  `embed` = function(self, texts, options = NULL) {
    a_texts <- as.character(texts)
    r <- .Call(R_rlx_model_embed, self, a_texts, length(a_texts), if (is.null(options)) NULL else .json(options))
    .check(r[[1]])
    .decode(r[[2]])
  }
)

Model <- .generator("Model", list(
